INSERT INTO politica_versoes (autor,nota,conteudo,hash,vigente) VALUES ('carga inicial','Política oficial, lida da planilha. A precedência é o que a GerencIA acrescenta.','{"origem": "Base de Dados — Starkbank apurada 15-09.xlsx, aba Regras_Risco", "regras": {"R01": {"nivel": "Crítico", "acao": "Bloquear/alertar e investigar", "ativa": true}, "R02": {"nivel": "Crítico", "acao": "Alerta imediato e investigação", "ativa": true}, "R03": {"nivel": "Crítico", "acao": "Alerta imediato; revogar/rotacionar credencial", "ativa": true}, "R04": {"nivel": "Crítico", "acao": "Investigar e aplicar resposta de privacidade", "ativa": true}, "R05": {"nivel": "Crítico", "acao": "Escalar para Compliance/Segurança", "ativa": true}, "R06": {"nivel": "Alto", "acao": "Investigar; avaliar exposição de PI", "ativa": true}, "R07": {"nivel": "Médio", "acao": "Registrar; validar finalidade e acesso", "ativa": true}, "R08": {"nivel": "Baixo", "acao": "Registrar sem alerta", "ativa": true}, "R09": {"nivel": "Baixo", "acao": "Permitido conforme finalidade", "ativa": true}, "R10": {"nivel": "Alto", "acao": "Revisar", "ativa": true}, "R11": {"nivel": "Alto", "acao": "Gerar alerta de volume", "ativa": true}, "R12": {"nivel": "Médio", "acao": "Registrar contexto", "ativa": true}, "R13": {"nivel": "Médio", "acao": "REVISAR", "ativa": true}, "R14": {"nivel": "Médio", "acao": "Sinalizar baixa rastreabilidade", "ativa": true}}, "precedencia": ["R14", "R13", "R03", "R05", "R04", "R06", "R02", "R01", "R11", "R10", "R07", "R09", "R08", "R12"], "limite_volume": 10}'::jsonb,'9c5333eafcedd63b3a7ac2249b373f1846c52d5e30ab6465e81fd49c86bc1b48',true);
INSERT INTO regras (id,tema,texto,nivel,acao,ordem) VALUES ('R01','Ferramenta não aprovada','Qualquer informação Confidencial em IA não aprovada','Crítico'::nivel_risco,'Bloquear/alertar e investigar',8) ON CONFLICT (id) DO NOTHING;
INSERT INTO regras (id,tema,texto,nivel,acao,ordem) VALUES ('R02','Ferramenta não aprovada','Qualquer informação Crítica em IA não aprovada','Crítico'::nivel_risco,'Alerta imediato e investigação',7) ON CONFLICT (id) DO NOTHING;
INSERT INTO regras (id,tema,texto,nivel,acao,ordem) VALUES ('R03','Credenciais','Secrets, tokens ou chaves em qualquer prompt/arquivo','Crítico'::nivel_risco,'Alerta imediato; revogar/rotacionar credencial',3) ON CONFLICT (id) DO NOTHING;
INSERT INTO regras (id,tema,texto,nivel,acao,ordem) VALUES ('R04','Dados pessoais','Dados pessoais identificáveis em IA pública','Crítico'::nivel_risco,'Investigar e aplicar resposta de privacidade',5) ON CONFLICT (id) DO NOTHING;
