INSERT INTO achados_auditoria (id,familia,gravidade,titulo,resumo,consequencia,evidencia,n_eventos,eventos) VALUES ('A-01','B','alta','Regra citada pressupõe ferramenta aprovada, mas a ferramenta não era','38 eventos ocorreram em IA Pública A ou B — ambas ''Não aprovada'' no cadastro — mas citam regras cujo texto diz ''em ferramenta aprovada'': R09 (29×), R08 (9×)','O nível de risco pode estar certo, mas a trilha de auditoria está errada. Um auditor que ler ''R09 — dados anonimizados em ferramenta aprovada'' num evento que aconteceu numa IA pública será induzido a erro. É a diferença entre registro e evidência.','Regras_Risco R08/R09 × coluna Status da aba Ferramentas_IA',38,ARRAY['["EVT-00039"',' "EVT-00048"',' "EVT-00073"',' "EVT-00094"',' "EVT-00110"',' "EVT-00149"',' "EVT-00152"',' "EVT-00165"',' "EVT-00174"',' "EVT-00185"',' "EVT-00227"',' "EVT-00235"',' "EVT-00242"',' "EVT-00265"',' "EVT-00268"',' "EVT-00290"',' "EVT-00327"',' "EVT-00333"',' "EVT-00337"',' "EVT-00361"',' "EVT-00374"',' "EVT-00407"',' "EVT-00432"',' "EVT-00439"',' "EVT-00444"',' "EVT-00449"',' "EVT-00454"',' "EVT-00462"',' "EVT-00484"',' "EVT-00496"',' "EVT-00547"',' "EVT-00570"',' "EVT-00577"',' "EVT-00584"',' "EVT-00596"',' "EVT-00600"',' "EVT-00639"',' "EVT-00644"]']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO achados_auditoria (id,familia,gravidade,titulo,resumo,consequencia,evidencia,n_eventos,eventos) VALUES ('A-02','C','alta','Regra genérica citada onde a política tem regra específica','18 eventos foram fechados com R01 ou R02 quando a política tem regra própria para o caso: R04 (11×), R05 (5×), R06 (2×)','As ações obrigatórias são diferentes. R01 manda ''bloquear/alertar e investigar''. R04 manda ''investigar e aplicar resposta de privacidade'' — o que inclui avaliar comunicação ao titular e à autoridade. Citar a regra genérica faz a obrigação de privacidade desaparecer do registro.','Regras_Risco R04/R05/R06 × Tipos_Informacao (categoria)',18,ARRAY['["EVT-00047"',' "EVT-00051"',' "EVT-00076"',' "EVT-00083"',' "EVT-00089"',' "EVT-00102"',' "EVT-00118"',' "EVT-00172"',' "EVT-00261"',' "EVT-00389"',' "EVT-00416"',' "EVT-00425"',' "EVT-00472"',' "EVT-00480"',' "EVT-00481"',' "EVT-00541"',' "EVT-00582"',' "EVT-00633"]']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO achados_auditoria (id,familia,gravidade,titulo,resumo,consequencia,evidencia,n_eventos,eventos) VALUES ('A-03','D','alta','Conteúdo não público na ferramenta aprovada só para conteúdo público','8 eventos usaram o Gerador de Imagens com informação Interna ou Confidencial. O cadastro diz que a ferramenta é ''Aprovada apenas para conteúdo público'' e que o controle é ''Não usar material confidencial''.','A base classificou esses eventos como Baixo ou Médio. Pela regra R10 — uso incompatível com a finalidade aprovada — eles são Alto. São eventos que deveriam ter virado alerta e não viraram.','Ferramentas_IA IA-08 (Status e Controles) × Regras_Risco R10',8,ARRAY['["EVT-00054"',' "EVT-00112"',' "EVT-00150"',' "EVT-00226"',' "EVT-00502"',' "EVT-00558"',' "EVT-00614"',' "EVT-00629"]']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO achados_auditoria (id,familia,gravidade,titulo,resumo,consequencia,evidencia,n_eventos,eventos) VALUES ('A-04','E','media','6 das 14 regras nunca são acionadas na base','Nunca aparecem na coluna ''Regra acionada'': R04, R05, R06, R12, R13, R14','Uma regra que nunca dispara ou está coberta por outra mais severa (R04, R05 e R06), ou não tem instrumentação para ser avaliada (R12, R13, R14). Nos dois casos ela dá uma falsa sensação de cobertura: a política aparenta ter catorze controles e opera com oito.','Regras_Risco × coluna ''Regra acionada'' de Eventos_Uso_IA',0,ARRAY['[]']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO achados_auditoria (id,familia,gravidade,titulo,resumo,consequencia,evidencia,n_eventos,eventos) VALUES ('A-05','F','media','Alertas não registram data de tratamento','47 alertas estão marcados como ''Tratado'', mas a aba Alertas não tem coluna de data de tratamento nem de desfecho.','O indicador ''Alertas críticos tratados em até 24h'' é declarado como 72% e não pode ser apurado a partir da base. Um indicador de SLA sem carimbo de tempo é uma afirmação, não uma medição.','Aba Alertas (colunas disponíveis) × Indicadores_Atuais',47,ARRAY['["ALT-0010"',' "ALT-0016"',' "ALT-0018"',' "ALT-0020"',' "ALT-0021"',' "ALT-0025"',' "ALT-0027"',' "ALT-0028"',' "ALT-0030"',' "ALT-0035"',' "ALT-0038"',' "ALT-0042"',' "ALT-0046"',' "ALT-0048"',' "ALT-0054"',' "ALT-0055"',' "ALT-0060"',' "ALT-0063"',' "ALT-0069"',' "ALT-0073"',' "ALT-0076"',' "ALT-0077"',' "ALT-0079"',' "ALT-0082"',' "ALT-0093"',' "ALT-0095"',' "ALT-0103"',' "ALT-0104"',' "ALT-0107"',' "ALT-0109"',' "ALT-0112"',' "ALT-0118"',' "ALT-0119"',' "ALT-0129"',' "ALT-0131"',' "ALT-0133"',' "ALT-0135"',' "ALT-0139"',' "ALT-0141"',' "ALT-0144"',' "ALT-0145"',' "ALT-0146"',' "ALT-0147"',' "ALT-0149"',' "ALT-0154"',' "ALT-0155"',' "ALT-0160"]']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO achados_auditoria (id,familia,gravidade,titulo,resumo,consequencia,evidencia,n_eventos,eventos) VALUES ('A-06','E','media','A política não cobre informação Interna ou Pública em ferramenta não aprovada','38 eventos caem nessa combinação Interna (29), Pública (9). Nenhuma das catorze regras trata dela.','O caso CV14 confirma que informação Pública nessa situação fica em Baixo, então o nível está certo. Para informação Interna não há gabarito: a política diz apenas ''preferir ferramentas corporativas aprovadas'', sem consequência definida. A GerencIA propõe a regra R15 para fechar a lacuna.','Regras_Risco (ausência) × Classificacao_Informacao (regra geral de Interna)',38,ARRAY['["EVT-00039"',' "EVT-00048"',' "EVT-00073"',' "EVT-00094"',' "EVT-00110"',' "EVT-00149"',' "EVT-00152"',' "EVT-00165"',' "EVT-00174"',' "EVT-00185"',' "EVT-00227"',' "EVT-00235"',' "EVT-00242"',' "EVT-00265"',' "EVT-00268"',' "EVT-00290"',' "EVT-00327"',' "EVT-00333"',' "EVT-00337"',' "EVT-00361"',' "EVT-00374"',' "EVT-00407"',' "EVT-00432"',' "EVT-00439"',' "EVT-00444"',' "EVT-00449"',' "EVT-00454"',' "EVT-00462"',' "EVT-00484"',' "EVT-00496"',' "EVT-00547"',' "EVT-00570"',' "EVT-00577"',' "EVT-00584"',' "EVT-00596"',' "EVT-00600"',' "EVT-00639"',' "EVT-00644"]']::text[]) ON CONFLICT (id) DO NOTHING;
